const data = $json;

let recoveryStatus = 'READY';
let recoveryReason = 'Recovery request passed validation.';

// 1. Processing error must still be OPEN
if (data.processing_error_status !== 'OPEN') {
  recoveryStatus = 'BLOCKED';
  recoveryReason = 'Processing error is no longer OPEN.';
}

// 2. Must be our supplier-email failure
else if (
  data.error_stage !== 'NOTIFICATION' ||
  data.error_code !== 'SUPPLIER_EMAIL_SEND_FAILED'
) {
  recoveryStatus = 'BLOCKED';
  recoveryReason = 'Processing error is not a supplier email send failure.';
}

// 3. Draft must still be FAILED
else if (data.draft_status !== 'FAILED') {
  recoveryStatus = 'BLOCKED';
  recoveryReason = `Draft status is ${data.draft_status}, not FAILED.`;
}

// 4. Email must not already have a confirmed sent_at
else if (data.sent_at !== null && data.sent_at !== undefined) {
  recoveryStatus = 'BLOCKED';
  recoveryReason = 'Draft already contains a sent timestamp.';
}

// 5. Original human email approval must remain APPROVED
else if (data.email_approval_status !== 'APPROVED') {
  recoveryStatus = 'BLOCKED';
  recoveryReason =
    `Email approval status is ${data.email_approval_status}, not APPROVED.`;
}

// 6. Recipient must still match supplier master data
else if (
  !data.recipient_email ||
  !data.current_supplier_email ||
  data.recipient_email.trim().toLowerCase() !==
    data.current_supplier_email.trim().toLowerCase()
) {
  recoveryStatus = 'BLOCKED';
  recoveryReason =
    'Draft recipient does not match the supplier current email address.';
}

// 7. Required email content must exist
else if (!data.email_subject || !data.email_subject.trim()) {
  recoveryStatus = 'BLOCKED';
  recoveryReason = 'Email subject is missing.';
}

else if (!data.email_body || !data.email_body.trim()) {
  recoveryStatus = 'BLOCKED';
  recoveryReason = 'Email body is missing.';
}

// 8. Decision must be supported
else if (!['RETRY', 'RESOLVE'].includes(data.recovery_decision)) {
  recoveryStatus = 'BLOCKED';
  recoveryReason = 'Unsupported recovery decision.';
}

return {
  json: {
    ...data,
    recovery_validation_status: recoveryStatus,
    recovery_validation_reason: recoveryReason,
    recovery_validated_at: new Date().toISOString()
  }
};

const data = $json;

const recipient = (data.recipient_email || '').trim().toLowerCase();
const subject = (data.email_subject || '').trim();
const body = (data.email_body || '').trim();

let sendSafetyStatus = 'READY_TO_SEND';
let sendSafetyReason = 'Recovery email passed final send safety validation.';

// Draft must have been atomically claimed
if (data.draft_status !== 'SENDING') {
  sendSafetyStatus = 'BLOCKED';
  sendSafetyReason =
    `Draft status is ${data.draft_status || 'missing'}, expected SENDING.`;
}

// Processing error must now be RETRYING
else if (data.processing_error_status !== 'RETRYING') {
  sendSafetyStatus = 'BLOCKED';
  sendSafetyReason =
    `Processing error status is ${data.processing_error_status || 'missing'}, expected RETRYING.`;
}

// Must still not have a confirmed send timestamp
else if (data.sent_at !== null && data.sent_at !== undefined) {
  sendSafetyStatus = 'BLOCKED';
  sendSafetyReason =
    'Email already has a sent timestamp.';
}

// Recipient required
else if (!recipient) {
  sendSafetyStatus = 'BLOCKED';
  sendSafetyReason =
    'Recipient email is missing.';
}

// Subject required
else if (!subject) {
  sendSafetyStatus = 'BLOCKED';
  sendSafetyReason =
    'Email subject is missing.';
}

// Body required
else if (!body) {
  sendSafetyStatus = 'BLOCKED';
  sendSafetyReason =
    'Email body is missing.';
}

// Test domains must NEVER reach Gmail
else if (
  recipient.endsWith('.example') ||
  recipient.endsWith('@example.com') ||
  recipient.endsWith('@example.org') ||
  recipient.endsWith('@example.net')
) {
  sendSafetyStatus = 'TEST_DOMAIN';
  sendSafetyReason =
    'Recipient uses a reserved test domain. Gmail sending is blocked.';
}

return {
  json: {
    ...data,
    send_safety_status: sendSafetyStatus,
    send_safety_reason: sendSafetyReason,
    send_safety_checked_at: new Date().toISOString()
  }
};
